const row = $('Loop Over CL Generate Rows (1 by 1)').last().json || {};
const pg = $input.first().json || {};
const resumeCtx = pg.resume_context || {};

const sNo = row['S. No.'];
const resumeId = (row['Resume_id'] && String(row['Resume_id']).trim() !== '')
  ? String(row['Resume_id']).trim()
  : (resumeCtx.resume_id || `RES-${sNo || Date.now()}`);

const rawCompany = String(row['Company'] || '').trim() || 'Hiring Organization';
const cleanCompany = rawCompany.replace(/[^a-zA-Z0-9_-]/g, '_').replace(/^_+|_+$/g, '') || 'Company';
const industry = String(row['Industry'] || '').trim() || 'Technology & Enterprise Operations';
const positionTitle = String(row['Position - Title'] || '').trim() || 'Senior Data & Business Analyst';
const rawJd = String(row['Position - Description'] || '').trim();
const aboutCompany = String(row['About Company'] || '').trim() || `An organization operating in ${industry}`;
const notesForCl = String(row['Notes for CL'] || '').trim();

const hrName = String(row['HR'] || '').trim();
const hasValidHrName = Boolean(hrName && hrName.toLowerCase() !== 'n/a' && hrName.toLowerCase() !== 'none');
const formattedDate = new Date().toLocaleDateString('en-US', {
  month: 'long',
  day: 'numeric',
  year: 'numeric',
  timeZone: 'Asia/Kolkata'
});
const recipientBlockHtml = hasValidHrName
  ? `<div>${hrName}</div><div>Talent Acquisition, ${rawCompany}</div>`
  : `<div>Hiring Team</div><div>${rawCompany}</div>`;
const greetingLine = hasValidHrName ? `Dear ${hrName},` : 'Dear Hiring Manager,';
const subjectRoleLabel = /\b(role|position)\b/i.test(positionTitle) ? positionTitle : `the ${positionTitle} Role`;

// Complete Industry-Standard Business Letter Header Block (Date + Recipient + Subject Line + Salutation)
const salutationHtml = `<div class="letter-meta">
  <div class="letter-date">${formattedDate}</div>
  <div class="recipient-block">
    ${recipientBlockHtml}
  </div>
  <div class="subject-line"><strong>Subject: Application for ${subjectRoleLabel}</strong></div>
</div>
<p class="salutation">${greetingLine}</p>`;

const defaultReference = {
  para1_hook_html: `<p>I am writing to apply for the ${positionTitle} role at ${rawCompany}. What stood out to me in the job description is the practical focus on turning messy day-to-day operations into clean data models and reliable reports. Before spending the last five years in data analytics, I ran my own small marketing agency for ten years. That mix taught me how much time teams lose when numbers do not match across different tools. Fixing those gaps between business teams and engineering is the part of the job I enjoy most.</p>`,
  para2_stewardship_html: `<p>Outside of writing SQL queries and building Tableau dashboards, I spend my free time on my terrace in Gurugram growing mushrooms and automating small daily tasks with n8n. Growing mushrooms in North India's weather is not a fancy hobby. It comes down to watching basic details closely. If moisture or airflow slips even a little, the whole batch fails. I bring that same habit to my work when I check data quality, map workflows, or build reports that leaders rely on.</p>`,
  para3_impact_story_html: `<p>I also believe analysis is only useful when it solves a real problem on the ground. At Concentrix, our hiring data showed that new joiners were struggling once they started work. Sending another dashboard to management was not fixing the issue. I looked closely at the hiring steps and worked with leadership to bring our training team directly into the interview stage. That simple change improved hire quality by 84%. In my current role at Highspring India, I use the same practical approach across four engineering teams to automate recurring reports and cut manual work by 40%.</p>`,
  para4_resilience_html: `<p>My day-to-day work covers SQL, Python, Tableau, and working closely with business and tech teams. If the team at ${rawCompany} uses an internal tool I have not worked with yet, I learn new systems quickly. Practical challenges early in my career taught me how to stay resourceful, focus on the basics, and get things done without hand-holding. When I take ownership of a task, nobody has to follow up twice.</p>`,
  para5_closing_html: `<p>I would welcome the chance to bring this steady, practical approach to ${rawCompany}. Thank you for your time and consideration, and I look forward to speaking with you soon.</p>`
};

const clRef = (pg.cl_reference && pg.cl_reference.para1_hook_html) ? pg.cl_reference : defaultReference;
const clRulesList = Array.isArray(pg.cl_rules) && pg.cl_rules.length > 0
  ? pg.cl_rules.map((r, i) => `${i + 1}. ${r}`).join('\n')
  : '1. Keep the cover letter strictly to 1 page (260-320 words total across 5 paragraphs). Write in short, simple, human-like sentences (12-18 words per sentence). Never say "your team" (refer to the company by name). Never use fancy words like disparate or stewardship.';

const effectiveJobDescription = rawJd.length >= 40
  ? rawJd
  : `Target Role: ${positionTitle} at ${rawCompany} (${industry}). About Company: ${aboutCompany}. Notes: ${notesForCl || 'None'}.`;

return [{
  json: {
    sNo,
    resumeId,
    company: rawCompany,
    cleanCompany,
    industry,
    positionTitle,
    jobDescription: effectiveJobDescription,
    aboutCompany,
    notesForCl,
    salutationHtml,
    roleCategory: resumeCtx.role_category || 'bi_data_analyst',
    jdBlueprint: resumeCtx.extracted_jd_keywords || {},
    clReference: clRef,
    clRules: clRulesList,
    _activeModel: 'gemini-3.5-flash-lite'
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  contents: [{
    parts: [{
      text: `You are writing a 1-page, plain-English, human-sounding Cover Letter for Sumanto Banerjee applying for ${$json.positionTitle} at ${$json.company} (${$json.industry}).

CANDIDATE REAL BACKGROUND (GROUND TRUTH — DO NOT INVENT FAKE FACTS):
- Current Role (Oct 2025 – Present): Sr. Data Analyst at Highspring India (On-site Google, Gurugram). Leads 3+ automation projects (cutting manual work by 40%), validates A/B tests across 15+ product launches, works across 4+ engineering and business teams, and works with 1M+ monthly records in SQL, Python, and Tableau.
- Prior Role (Apr 2022 – Aug 2025): Lead Trainer at Concentrix Daksh (Gurugram). Analyzed hiring and workforce data; instead of just sending management another dashboard, worked with leadership to bring the training team directly into the interview stage, improving hire quality by 84% and boosting team productivity by 25%.
- Earlier Career (2010 – 2020): Founder at Maerke Stratcomm (Delhi) for 10 years, running client projects and growing HORECA sales by 25% for Wild Vitamin Drink. B.Comm (Hons.) from University of Delhi.
- Real Hobbies Outside Work: Growing mushrooms on his terrace in Gurugram (watching basic details like moisture and airflow closely) and automating small daily tasks with n8n.

STUDY THIS GOLD-STANDARD HUMAN-WRITTEN SAMPLE (MATCH ITS SHORT SENTENCES & SIMPLE VOCABULARY):
- Paragraph 1: ${$json.clReference.para1_hook_html}
- Paragraph 2: ${$json.clReference.para2_stewardship_html}
- Paragraph 3: ${$json.clReference.para3_impact_story_html}
- Paragraph 4: ${$json.clReference.para4_resilience_html}
- Paragraph 5: ${$json.clReference.para5_closing_html}

INPUTS FOR THIS APPLICATION:
- COMPANY: ${$json.company} (${$json.industry})
- ABOUT COMPANY: ${$json.aboutCompany}
- POSITION TITLE: ${$json.positionTitle}
- USER NOTES FOR COVER LETTER ('Notes for CL'): ${$json.notesForCl || 'None provided — open plainly with why the day-to-day work in the Job Description fits Sumanto.'}
- JOB DESCRIPTION:
${String($json.jobDescription || '').slice(0, 2500)}

MANDATORY LEARNED RULES FROM PAST REVIEWS (MUST OBEY):
${$json.clRules}

STRICT HUMAN-WRITING & SHORT-SENTENCE RULES (CRITICAL):
1. KEEP SENTENCES SHORT (12 TO 18 WORDS PER SENTENCE, MAX 20 WORDS):
   - Never write long, winding 30+ word sentences.
   - If a sentence has more than one comma, break it into two separate sentences with a period.
   - NEVER use em-dashes (—) or semicolons (;) to chain clauses together. Use a period and start a new sentence.
2. NEVER SAY 'YOUR TEAM' (HR-AWARE RECIPIENT RULE):
   - The letter is often read first by HR / Talent Acquisition, NOT the hiring manager you will report to.
   - Therefore, NEVER write 'your team' (e.g., do NOT write 'bring this approach to your team' or 'if your team uses').
   - Instead, always refer to the company by name ('${$json.company}') or 'the analytics team at ${$json.company}' (e.g., 'bring this steady, practical approach to ${$json.company}' and 'If the team at ${$json.company} uses an internal tool...').
3. USE SIMPLE, EVERYDAY SPOKEN WORDS (NO FANCY OR AI WORDS):
   - BANNED WORDS: NEVER use words like 'disparate', 'stewardship', 'rigorous', 'multifaceted', 'synergetic', 'delve', 'testament', 'orchestrate', 'leverage', 'paradigm', 'overarching', 'intersection', 'friction', 'structural adjustment', 'operational funnel', 'cohort', 'proprietary', 'hygiene', 'ecosystem', 'spearhead', 'unwavering', 'landscape', 'tapestry', 'seamless', or 'catalyze'.
   - Use plain human words instead: say 'different tools' (not 'disparate systems'), 'close attention' or 'habit' (not 'rigorous stewardship'), 'new joiners' (not 'cohorts'), 'hiring steps' (not 'operational funnel'), 'simple change' (not 'structural adjustment').
4. STRICT 1-PAGE WORD BUDGET (260 TO 320 WORDS TOTAL ACROSS 5 PARAGRAPHS):
   - Paragraph 1 (para1_hook_html, 4-5 short sentences, ~65 words): State what stood out in the ${$json.positionTitle} JD at ${$json.company}. Mention his 5 years in data analytics after 10 years running his own small agency. Explain simply that he likes fixing data gaps between business and tech teams.
   - Paragraph 2 (para2_stewardship_html, 4-5 short sentences, ~65 words): Mention his terrace mushroom growing in Gurugram and n8n automation hobby in plain, humble terms (watching moisture and airflow closely so the batch does not fail), and connect that habit to the day-to-day responsibilities in this JD.
   - Paragraph 3 (para3_impact_story_html, 4-5 short sentences, ~75 words): Tell the Concentrix story (bringing the training team into interviews to improve hire quality by 84%) and/or the Highspring India work (automating recurring reports across four engineering teams to cut manual work by 40%) in short, clear sentences.
   - Paragraph 4 (para4_resilience_html, 3-4 short sentences, ~55 words): Mention his core stack (SQL, Python, Tableau) and state honestly that if the team at ${$json.company} uses an internal tool he has not worked with yet, he learns fast, stays resourceful, and is dependable.
   - Paragraph 5 (para5_closing_html, ONE single <p> tag with 2 short sentences, ~30 words): 'I would welcome the chance to bring this steady, practical approach to ${$json.company}. Thank you for your time and consideration, and I look forward to speaking with you soon.'
5. NO BOLD TAGS IN BODY PARAGRAPHS: Do NOT put <strong> or <b> tags inside the paragraphs.

Return STRICT JSON only (no markdown fences) matching this exact schema:
{
  "para1_hook_html": "<p>...</p>",
  "para2_stewardship_html": "<p>...</p>",
  "para3_impact_story_html": "<p>...</p>",
  "para4_resilience_html": "<p>...</p>",
  "para5_closing_html": "<p>...</p>"
}`
    }]
  }],
  generationConfig: String($json._activeModel || '').startsWith('gemma')
    ? { temperature: 0.25 }
    : { temperature: 0.25, responseMimeType: "application/json" }
}) }}

