const FALLBACK_MODELS = [
  'gemini-3.5-flash-lite',
  'gemini-2.5-flash-lite',
  'gemini-2.5-flash',
  'gemini-2.0-flash-lite',
  'gemini-2.0-flash',
  'gemini-1.5-flash',
  'gemma-2-27b-it'
];
const upstream = $('Prepare Grounded Cover Letter Context').last().json;
const staticData = $getWorkflowStaticData('node');
const rowKey = String(upstream.sNo || upstream.resumeId || 'row');
if (staticData.lastRowKey !== rowKey) {
  staticData.lastRowKey = rowKey;
  staticData.failCount = 0;
}
staticData.failCount = (staticData.failCount || 0) + 1;
if (staticData.failCount > 14) {
  throw new Error(`All 7 fallback AI models overloaded at CL Generator after ${staticData.failCount} switches.`);
}
const nextModel = FALLBACK_MODELS[staticData.failCount % FALLBACK_MODELS.length];
return [{ json: { ...upstream, _activeModel: nextModel, _failoverAttempt: staticData.failCount } }];

const ctx = $('Prepare Grounded Cover Letter Context').last().json;
const rawText = $('Gemini: Generate 1-Page Grounded Cover Letter').last().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleanJson = String(rawText).replace(/```json|```/gi, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {};
}

// Post-processor to enforce human-like plain English, HR-aware phrasing, no mid-sentence bolding, no em-dashes, and 1 <p> per paragraph
const cleanHumanParagraph = (val, fallback) => {
  let s = String(val || '').replace(/```html|```/gi, '').trim();
  if (s.length < 15) s = String(fallback || '').trim();
  // Merge any split </p><p> inside a single paragraph slot
  s = s.replace(/<\/p>\s*<p[^>]*>/gi, ' ');
  // Remove mid-paragraph <strong> and <b> tags so body text looks human-written
  s = s.replace(/<\/?(strong|b)>/gi, '');
  // Replace em-dashes with clean punctuation
  s = s.replace(/\s*—\s*/g, ', ').replace(/,\s*,/g, ',');
  // Replace 'your team' with HR-aware company phrasing
  s = s.replace(/\bto your team\b/gi, `to ${ctx.company}`)
       .replace(/\bIf your team uses\b/gi, `If the team at ${ctx.company} uses`)
       .replace(/\bif your team uses\b/gi, `if the team at ${ctx.company} uses`)
       .replace(/\bspeaking with your team\b/gi, 'speaking with you');
  // Replace common fancy AI words if any slipped through
  s = s.replace(/\bdisparate\b/gi, 'different')
       .replace(/\brigorous stewardship\b/gi, 'close attention to detail')
       .replace(/\bpractical stewardship\b/gi, 'close attention to detail')
       .replace(/\bstewardship\b/gi, 'care')
       .replace(/\brigorous\b/gi, 'careful')
       .replace(/\boperational funnel\b/gi, 'hiring process')
       .replace(/\bstructural adjustment\b/gi, 'simple change')
       .replace(/\bstrategic friction\b/gi, 'confusion')
       .replace(/\bdata hygiene\b/gi, 'data accuracy')
       .replace(/\bnew cohorts\b/gi, 'new joiners')
       .replace(/\bcohorts\b/gi, 'batches');
  if (!s.startsWith('<p')) s = `<p>${s}</p>`;
  return s;
};

const paras = {
  para1_hook_html: cleanHumanParagraph(parsed.para1_hook_html, ctx.clReference.para1_hook_html),
  para2_stewardship_html: cleanHumanParagraph(parsed.para2_stewardship_html, ctx.clReference.para2_stewardship_html),
  para3_impact_story_html: cleanHumanParagraph(parsed.para3_impact_story_html, ctx.clReference.para3_impact_story_html),
  para4_resilience_html: cleanHumanParagraph(parsed.para4_resilience_html, ctx.clReference.para4_resilience_html),
  para5_closing_html: cleanHumanParagraph(parsed.para5_closing_html, ctx.clReference.para5_closing_html)
};

// Calculate plain-text character count to dynamically auto-fit CSS so the PDF is GUARANTEED 1 Page
const combinedHtml = `${paras.para1_hook_html}${paras.para2_stewardship_html}${paras.para3_impact_story_html}${paras.para4_resilience_html}${paras.para5_closing_html}`;
const plainTextLen = combinedHtml.replace(/<[^>]+>/g, '').length;

let pageMargin = '0.62in 0.75in';
let bodyFontSize = '10.3pt';
let bodyLineHeight = '1.45';
let paraMarginBottom = '11px';
let headerMarginBottom = '18px';
let signOffMarginTop = '18px';

if (plainTextLen > 2350) {
  pageMargin = '0.48in 0.68in';
  bodyFontSize = '9.6pt';
  bodyLineHeight = '1.34';
  paraMarginBottom = '8.5px';
  headerMarginBottom = '14px';
  signOffMarginTop = '12px';
} else if (plainTextLen > 2000) {
  pageMargin = '0.55in 0.72in';
  bodyFontSize = '10.0pt';
  bodyLineHeight = '1.40';
  paraMarginBottom = '9.5px';
  headerMarginBottom = '16px';
  signOffMarginTop = '15px';
}

const clCss = `
  @page {
    size: A4;
    margin: ${pageMargin};
  }
  * {
    box-sizing: border-box;
  }
  body {
    font-family: 'Georgia', 'Times New Roman', serif;
    font-size: ${bodyFontSize};
    line-height: ${bodyLineHeight};
    color: #111111;
    margin: 0;
    padding: 0;
  }
  .cl-header {
    text-align: center;
    margin-bottom: ${headerMarginBottom};
    border-bottom: 1px solid #222222;
    padding-bottom: 10px;
  }
  .cl-header h1 {
    font-size: 22pt;
    font-weight: normal;
    margin: 0 0 4px 0;
    letter-spacing: 0.3px;
    color: #111111;
  }
  .cl-contact {
    font-size: 9.6pt;
    color: #222222;
    margin-bottom: 2px;
  }
  .cl-contact a {
    color: #1155cc;
    text-decoration: none;
  }
  .cl-location {
    font-size: 9.6pt;
    color: #333333;
  }
  .letter-meta {
    margin-bottom: 12px;
    line-height: 1.38;
    text-align: left;
  }
  .letter-date {
    margin-bottom: 10px;
    color: #222222;
  }
  .recipient-block {
    margin-bottom: 10px;
    color: #111111;
  }
  .subject-line {
    margin-bottom: 12px;
    color: #111111;
  }
  p {
    margin: 0 0 ${paraMarginBottom} 0;
    text-align: justify;
  }
  p.salutation {
    margin-bottom: 11px;
    text-align: left;
  }
  strong {
    font-weight: bold;
    color: #000000;
  }
  .sign-off {
    margin-top: ${signOffMarginTop};
    page-break-inside: avoid;
    break-inside: avoid;
    text-align: left;
  }
  .sign-off p {
    text-align: left;
  }
`;

const fullHtml = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Sumanto_Banerjee-Cover_Letter-${ctx.cleanCompany}</title>
  <style>${clCss}</style>
</head>
<body>
  <div class="cl-header">
    <h1>Sumanto Banerjee</h1>
    <div class="cl-contact">REDACTED_EMAIL@example.com &nbsp;|&nbsp; +91-8802444912 &nbsp;|&nbsp; <a href="https://www.linkedin.com/in/sumanto-banerjee/">LinkedIn Profile</a></div>
    <div class="cl-location">Gurugram, Haryana, India</div>
  </div>

  ${ctx.salutationHtml}
  ${paras.para1_hook_html}
  ${paras.para2_stewardship_html}
  ${paras.para3_impact_story_html}
  ${paras.para4_resilience_html}
  ${paras.para5_closing_html}

  <div class="sign-off">
    <p style="margin-bottom: 6px;">Sincerely,</p>
    <p><strong>Sumanto Banerjee</strong></p>
  </div>
</body>
</html>`;

const fileName = `Sumanto_Banerjee-Cover_Letter-${ctx.cleanCompany}.pdf`;

return [{
  json: {
    ...ctx,
    paras,
    plainTextLen,
    pdfFileName: fileName
  },
  binary: {
    index_html: await this.helpers.prepareBinaryData(Buffer.from(fullHtml, 'utf8'), 'index.html', 'text/html')
  }
}];

const sheetRow = $('Loop Over CL Review Rows (1 by 1)').last().json || {};
const pgOut = $input.first().json || {};
const dbRow = pgOut.cached_cl || {};
const activeRules = Array.isArray(pgOut.active_cl_rules) ? pgOut.active_cl_rules : [];

const notesForCl = String(sheetRow['Notes for CL'] || '').trim();
const notesByReviewer = String(sheetRow['Notes by Reviewer'] || '').trim();
const genericNotes = String(sheetRow['Notes'] || '').trim();

const reviewerNotes = [notesForCl, notesByReviewer, genericNotes]
  .filter(n => n && n.toLowerCase() !== 'none provided')
  .join('\n');

// Detect if user wrote 'For this cover letter' or 'For this resume' (one-off edit that must NOT be saved globally)
const isForThisClOnly = /\b(for this cover letter|for this cl|this cover letter only|only for this cover letter|for this resume|this resume only|only for this resume|just for this)\b/i.test(reviewerNotes);

const sNo = String(sheetRow['S. No.'] || dbRow.s_no || '');
const resumeId = String(dbRow.resume_id || sheetRow['Resume_id'] || `RES-${sNo || Date.now()}`);
const company = String(sheetRow['Company'] || dbRow.company_name || 'Hiring Organization').trim();
