const formattedDate = new Date().toLocaleDateString('en-US', {
  month: 'long',
  day: 'numeric',
  year: 'numeric',
  timeZone: 'Asia/Kolkata'
});
const recipientBlockHtml = hasValidHrName
  ? `<div>${hrName}</div><div>Talent Acquisition, ${company}</div>`
  : `<div>Hiring Team</div><div>${company}</div>`;
const greetingLine = hasValidHrName ? `Dear ${hrName},` : 'Dear Hiring Manager,';
