const FALLBACK_MODELS = [
  'gemini-3.5-flash-lite',
  'gemini-2.5-flash-lite',
  'gemini-2.5-flash',
  'gemini-2.0-flash-lite',
  'gemini-2.0-flash',
  'gemini-1.5-flash',
  'gemma-2-27b-it'
];
const upstream = $('Merge CL Feedback & Cached Paragraphs').last().json;
const staticData = $getWorkflowStaticData('node');
const rowKey = String(upstream.sNo || upstream.resumeId || 'row');
if (staticData.lastRowKey !== rowKey) {
  staticData.lastRowKey = rowKey;
  staticData.failCount = 0;
}
staticData.failCount = (staticData.failCount || 0) + 1;
if (staticData.failCount > 14) {
  throw new Error(`All 7 fallback AI models overloaded at CL Reviewer after ${staticData.failCount} switches.`);
}
const nextModel = FALLBACK_MODELS[staticData.failCount % FALLBACK_MODELS.length];
return [{ json: { ...upstream, _activeModel: nextModel, _failoverAttempt: staticData.failCount } }];

const ctx = $('Merge CL Feedback & Cached Paragraphs').last().json;
const rawText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
const cleanJson = String(rawText).replace(/```json|```/gi, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {};
}

const cleanHumanParagraph = (val, fallback) => {
  let s = String(val || '').replace(/```html|```/gi, '').trim();
  if (s.length < 15) s = String(fallback || '').trim();
  s = s.replace(/<\/p>\s*<p[^>]*>/gi, ' ');
  s = s.replace(/<\/?(strong|b)>/gi, '');
  s = s.replace(/\s*—\s*/g, ', ').replace(/,\s*,/g, ',');
  s = s.replace(/\bto your team\b/gi, `to ${ctx.company}`)
       .replace(/\bIf your team uses\b/gi, `If the team at ${ctx.company} uses`)
       .replace(/\bif your team uses\b/gi, `if the team at ${ctx.company} uses`)
       .replace(/\bspeaking with your team\b/gi, 'speaking with you');
  s = s.replace(/\bdisparate\b/gi, 'different')
       .replace(/\brigorous stewardship\b/gi, 'close attention to detail')
       .replace(/\bpractical stewardship\b/gi, 'close attention to detail')
       .replace(/\bstewardship\b/gi, 'care')
       .replace(/\brigorous\b/gi, 'careful')
       .replace(/\boperational funnel\b/gi, 'hiring process')
       .replace(/\bstructural adjustment\b/gi, 'simple change')
       .replace(/\bstrategic friction\b/gi, 'confusion')
       .replace(/\bdata hygiene\b/gi, 'data accuracy')
       .replace(/\bnew cohorts\b/gi, 'new joiners')
       .replace(/\bcohorts\b/gi, 'batches');
  if (!s.startsWith('<p')) s = `<p>${s}</p>`;
  return s;
};

const para1_hook_html = cleanHumanParagraph(parsed.para1_hook_html, ctx.para1_hook_html);
const para2_stewardship_html = cleanHumanParagraph(parsed.para2_stewardship_html, ctx.para2_stewardship_html);
const para3_impact_story_html = cleanHumanParagraph(parsed.para3_impact_story_html, ctx.para3_impact_story_html);
const para4_resilience_html = cleanHumanParagraph(parsed.para4_resilience_html, ctx.para4_resilience_html);
const para5_closing_html = cleanHumanParagraph(parsed.para5_closing_html, ctx.para5_closing_html);

const isOneOff = Boolean(
  ctx.isForThisClOnly ||
  String(parsed.rule_scope || '').toUpperCase() === 'NONE' ||
  /\b(for this cover letter|for this cl|this cover letter only|only for this cover letter|for this resume|this resume only|only for this resume|just for this)\b/i.test(String(parsed.permanent_learned_rule || ''))
);

const extractedRule = isOneOff ? '' : String(parsed.permanent_learned_rule || '').trim();
const shouldSaveLearnedRule = !isOneOff && extractedRule.length > 5;

const combinedHtml = `${para1_hook_html}${para2_stewardship_html}${para3_impact_story_html}${para4_resilience_html}${para5_closing_html}`;
const plainTextLen = combinedHtml.replace(/<[^>]+>/g, '').length;

let pageMargin = '0.62in 0.75in';
let bodyFontSize = '10.3pt';
let bodyLineHeight = '1.45';
let paraMarginBottom = '11px';
let headerMarginBottom = '18px';
let signOffMarginTop = '18px';

if (plainTextLen > 2350) {
  pageMargin = '0.48in 0.68in';
  bodyFontSize = '9.6pt';
  bodyLineHeight = '1.34';
  paraMarginBottom = '8.5px';
  headerMarginBottom = '14px';
  signOffMarginTop = '12px';
} else if (plainTextLen > 2000) {
  pageMargin = '0.55in 0.72in';
  bodyFontSize = '10.0pt';
  bodyLineHeight = '1.40';
  paraMarginBottom = '9.5px';
  headerMarginBottom = '16px';
  signOffMarginTop = '15px';
}

const clCss = `
  @page { size: A4; margin: ${pageMargin}; }
  * { box-sizing: border-box; }
  body { font-family: 'Georgia', 'Times New Roman', serif; font-size: ${bodyFontSize}; line-height: ${bodyLineHeight}; color: #111111; margin: 0; padding: 0; }
  .cl-header { text-align: center; margin-bottom: ${headerMarginBottom}; border-bottom: 1px solid #222222; padding-bottom: 10px; }
  .cl-header h1 { font-size: 22pt; font-weight: normal; margin: 0 0 4px 0; letter-spacing: 0.3px; color: #111111; }
  .cl-contact { font-size: 9.6pt; color: #222222; margin-bottom: 2px; }
  .cl-contact a { color: #1155cc; text-decoration: none; }
  .cl-location { font-size: 9.6pt; color: #333333; }
  .letter-meta { margin-bottom: 12px; line-height: 1.38; text-align: left; }
  .letter-date { margin-bottom: 10px; color: #222222; }
  .recipient-block { margin-bottom: 10px; color: #111111; }
  .subject-line { margin-bottom: 12px; color: #111111; }
  p { margin: 0 0 ${paraMarginBottom} 0; text-align: justify; }
  p.salutation { margin-bottom: 11px; text-align: left; }
  strong { font-weight: bold; color: #000000; }
  .sign-off { margin-top: ${signOffMarginTop}; page-break-inside: avoid; break-inside: avoid; text-align: left; }
  .sign-off p { text-align: left; }
`;

const fullHtml = `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8" /><title>Sumanto_Banerjee-Cover_Letter-${ctx.cleanCompany}_v${ctx.nextRevision}</title><style>${clCss}</style></head>
<body>
  <div class="cl-header">
    <h1>Sumanto Banerjee</h1>
    <div class="cl-contact">REDACTED_EMAIL@example.com &nbsp;|&nbsp; +91-8802444912 &nbsp;|&nbsp; <a href="https://www.linkedin.com/in/sumanto-banerjee/">LinkedIn Profile</a></div>
    <div class="cl-location">Gurugram, Haryana, India</div>
  </div>
  ${ctx.salutationHtml}
  ${para1_hook_html}
  ${para2_stewardship_html}
  ${para3_impact_story_html}
  ${para4_resilience_html}
  ${para5_closing_html}
  <div class="sign-off"><p style="margin-bottom: 6px;">Sincerely,</p><p><strong>Sumanto Banerjee</strong></p></div>
</body></html>`;

return [{
  json: {
    ...ctx,
    extractedRule,
    shouldSaveLearnedRule,
    para1_hook_html,
    para2_stewardship_html,
    para3_impact_story_html,
    para4_resilience_html,
    para5_closing_html,
    pdfFileName: `Sumanto_Banerjee-Cover_Letter-${ctx.cleanCompany}_v${ctx.nextRevision}.pdf`
  },
  binary: {
    index_html: await this.helpers.prepareBinaryData(Buffer.from(fullHtml, 'utf8'), 'index.html', 'text/html')
  }
}];
